var s=`1068-bak-kut-teh`;var n=`world-1068`;var t=`SG`;var a=`southeast-asia`;var r=4;var o=133;var g={en:`Bak Kut Teh`,ua:`Бак кут те`};var m={en:`Bak Kut Teh is a dish from Singapore prepared with pork ribs, garlic, dark soy sauce, light soy sauce. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Бак кут те, страва кухні країни Сінгапур, яку готують із таких продуктів: свинячі ребра, часник, темний соєвий соус, світлий соєвий соус. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 95 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 95 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:95,i:[[`pork-ribs`,1e3,`g`],[`water`,1600,`ml`],[`garlic`,8,`clove`],[`ground-white-pepper`,9,`g`],[`star-anise`,2,`pcs`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`dark-soy-sauce`,20,`ml`],[`light-soy-sauce`,30,`ml`],[`shiitake-mushroom`,200,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`],[`green-onion`,30,`g`]]}];var h={slug:s,id:n,country:`SG`,region:a,servings:4,minutes:133,title:g,text:m,steps:u};export{t as country,h as default,n as id,o as minutes,a as region,r as servings,s as slug,u as steps,m as text,g as title};